import { ccc } from "@ckb-ccc/connector-react";
import Counter from "./components/Counter";

function App() {
  return (
    <div style={{ minHeight: "100vh", background: "#0b0b0b", color: "#fff" }}>
      {/* HEADER */}
      <header
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          padding: "16px 32px",
          borderBottom: "1px solid #222",
        }}
      >
        <h2>CKB On-Chain Counter</h2>

        {/* ✅ CUSTOM CONNECT BUTTON */}
        <ccc.Connector>
          {(props) => (
            <button
              onClick={props.open}
              style={{
                padding: "10px 16px",
                background: "#4f46e5",
                color: "#fff",
                border: "none",
                borderRadius: "8px",
                cursor: "pointer",
                fontWeight: 600,
              }}
            >
              {props.connected ? "Wallet Connected" : "Connect Wallet"}
            </button>
          )}
        </ccc.Connector>
      </header>

      {/* CONTENT */}
      <main style={{ padding: 32 }}>
        <Counter />
      </main>
    </div>
  );
}

export default App;
